CREATE TABLE CATEGORIAS (
  id INT PRIMARY KEY,
  nome varchar(100)
);

CREATE TABLE clientes (
  id INT PRIMARY KEY,

  nome VARCHAR(200),
  cidade VARCHAR(200),
  uf VARCHAR(2),
  status BOOLEAN,

  data_churn TIMESTAMP,
  created_at TIMESTAMP,
  updated_at TIMESTAMP
);

CREATE TABLE LOJAS (
  id INT PRIMARY KEY,
  nome VARCHAR(200),
  cidade VARCHAR(200),
  uf VARCHAR(2),

  created_at TIMESTAMP,
  updated_at TIMESTAMP
);

CREATE TABLE ENTREGADORES (
  id INT PRIMARY KEY,
  loja_id INT,

  nome VARCHAR(200),
  dt_admissao TIMESTAMP,
  ativo BOOLEAN,

  CONSTRAINT fk_entregadores_lojas FOREIGN KEY (loja_id)
    REFERENCES LOJAS(id)
);

CREATE TABLE PRODUTOS (
  id INT PRIMARY KEY,
  categoria_id INT, --(bebidas quentes, frias, snacks)

  nome VARCHAR(250),
  estoque_atual INT,
  estoque_minimo INT,
  preco_tabela DECIMAL(10,2),
  custo_unitario DECIMAL(10, 2),
  ativo BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMP,
  updated_at TIMESTAMP,

  CONSTRAINT fk_produtos_categorias FOREIGN KEY (categoria_id)
    REFERENCES CATEGORIAS(id)
);

CREATE TABLE PEDIDOS (
  id INT PRIMARY KEY,
  loja_id INT,
  entregador_id INT, 
  cliente_id INT,

  status INT, --(recebido, entregue, cancelado)
  dt_pedido TIMESTAMP, 
  dt_entrega TIMESTAMP,

  CONSTRAINT fk_pedidos_lojas FOREIGN KEY (loja_id)
    REFERENCES LOJAS(id),

  CONSTRAINT fk_pedidos_entregadores FOREIGN KEY (entregador_id)
    REFERENCES ENTREGADORES(id),

  CONSTRAINT fk_pedidos_clientes FOREIGN KEY (cliente_id)
     REFERENCES CLIENTES(id) 
);

CREATE TABLE ITENS_PEDIDO (
  id INT PRIMARY KEY,
  pedido_id INT,
  produto_id INT,
  
  quantidade INT,
  valor_unitario DECIMAL(10,2),
  valor_desconto DECIMAL(10, 2),

  CONSTRAINT fk_itens_pedido_pedidos FOREIGN KEY (pedido_id)
    REFERENCES PEDIDOS(id),

  CONSTRAINT fk_itens_pedido_produtos FOREIGN KEY (produto_id)
    REFERENCES PRODUTOS(id)
);


